      retriedCount: retryCount,
      totalAttempted: failedEvents.length
    };
  }

  /**
   * 테스트 이벤트 시뮬레이션
   */
  async simulateEvent(action, repositoryName) {
    return await this.handleEvent({
      action,
      repository: {
        id: Math.floor(Math.random() * 10000),
        full_name: repositoryName,
