#!/usr/bin/env node

/**
 * MonitoringSystem 종합 테스트
 *
 * 테스트 범위:
 * 1. 요청 메트릭 기록
 * 2. 응답 시간 분석
 * 3. 엔드포인트별 통계
 * 4. 시간별 데이터 집계
 * 5. 알림 시스템
 * 6. 대시보드 데이터
 * 7. 헬스 리포트
 */

import MonitoringSystem from './monitoring-system.js';

class TestRunner {
  constructor() {
    this.tests = [];
    this.passed = 0;
    this.failed = 0;
  }

  test(name, fn) {
    this.tests.push({ name, fn });
  }

  async run() {
    console.log('\n' + '='.repeat(70));
    console.log('🧪 MonitoringSystem 종합 테스트');
    console.log('='.repeat(70) + '\n');

    for (const { name, fn } of this.tests) {
      try {
        await fn();
        this.passed++;
        console.log(`✅ ${name}`);
      } catch (error) {
        this.failed++;
        console.log(`❌ ${name}`);
        console.log(`   → ${error.message}`);
      }
    }

    console.log('\n' + '='.repeat(70));
    console.log(`📊 테스트 결과: ${this.passed}/${this.passed + this.failed} (${this.failed > 0 ? '❌' : '✅'})`);
    console.log('='.repeat(70) + '\n');

    process.exit(this.failed > 0 ? 1 : 0);
  }
}

const runner = new TestRunner();

// ============================================================
// 1. 요청 메트릭 기록
// ============================================================

runner.test('요청 메트릭 기록', () => {
  const mon = new MonitoringSystem();
